function languageOf(language: PromptLanguage): PromptLanguage {
  return LANGUAGES.includes(language) ? language : 'es';
}

export function deepResearchQualityPromptPack(language: PromptLanguage = 'es', approachRules: readonly string[] = []): DeepResearchQualityPromptPack {
  const lang = languageOf(language);
  return {
    editorialReview: EDITORIAL[lang],
    coherenceCheck: COHERENCE[lang],
    citationVerifier: VERIFIER[lang],
    candidateJudge: JUDGE[lang],
    claimsAudit: CLAIMS[lang](approachRules),
  };
}
